  int k;          // Class Member
   T0 shift_output;
  void exec(T1 *pcout, T0 *dataOut, T1 pcin, T3 coeff, T0 data, int col)
  {
 Function_label0:;
 #pragma HLS inline off
  SRL:for (k = N-1; k >= 0; --k) {
 #pragma HLS unroll // Loop will fail UNROLL
  if (k > 0)
  shift[k] = shift[k-1];
  else
  shift[k] = data;
