This is the list of registers that can be used to configure each intrinsic template to use the

corresponding register in the RTL model:

• REG_A1, REG_A2 on input A

• REG_B1, REG_B2 on input B

Unsigned     Inputs

The DSP48 and DSP58 both contain signed multipliers. This implies that when using DSP

intrinsics to multiply unsigned values, one must explicitly create them by setting the MSB to 0,
otherwise an unsigned input with the MSB set to 1 would be interpreted as a negative number.

The easiest mechanism is to explicitly use unsigned types with one less bit.

For Example:

 #include "hls_dsp_builtins.h"
 using namespace hls::dsp58;
 ...
 ap_uint<57> test(ap_uint<26> d, ap_uint<26> a, ap_uint<23> b, ap_uint<57>
 c) {
    return add_mul_add<...>((ap_uint<27>(d), ap_uint<27>(a),
 ap_uint<24>(b), ap_uint<58>(c));
 }

• That can be instantiated to infer different DSP accumulator instances (just one in the example

  below).

• Has two methods mul_acc (P = A * B + P) and add_mul_acc (P = (A + D) * B + P).

    Performs an accumulation and returns its result (i.e. register P).
  ○
    If the initialization condition is true (in the case below when iteration variable is 0), resets
  ○
    register P to 0.

 mul_acc      P += A * B     template <int64_t flags> C_t mul_acc( A_t a, B_t b, bool init);

 add_mul_acc  P += (A + D) * B template <int64_t flags> C_t mul_acc( D_t D, A_t a, B_t b, bool init);

This is a simple example computing a FIR filter, using the namespace hls::dsp48e2 to expose

the acc<> class and the REG_P and REG_M symbols:

 #include "hls_dsp_builtins.h"
 using namespace hls::dsp48e2;
 ...
 long test_mul_acc(long delay[N], long coeff[N])
 {
    acc<REG_P|REG_M> my_acc;
    C_t res;
    for (int i=0; i<N; i++) {
       res = my_acc.mul_acc(delay[i], coeff[i], /* init condition */ i==0);
    }
    return res;
 }

DSP   Cascading

It is also possible to generate an RTL that Vivado can use (if allowed by the placement) to

cascade DSPs via the direct ACIN, BCIN and PCIN inputs and ACOUT, BCOUT and PCOUT
outputs

This can be achieved by instantiating the hls::dsp(48e1|48e2|58)::cascade class.

The class has a public method called mul_add (more methods will be added in the future) to

perform the required operation with the cascaded inputs from the previous stage and return the
cascaded outputs.

Return Struct

 struct R_t {
  A_t acout;
  B_t bcout;
  C_t pcout;
 };
 R_t mul_add(A_t a, B_t b, C_t c);

The result of mul_add is a struct that allows the designer to chain the DSP for example, from

BCOUT output port to BCIN input port as shown in this example, which models a templated FIR
with size taps and using the systolic cascaded architecture.

 #include "hls_dsp_builtins.h"
 using namespace hls::dsp48e2;
 ...
 template <int size>
 class FIR {
     private:
        const long* coeff_;
        long bias_;
        cascade<REG_A1 | REG_B1 | REG_M | REG_P > dsp0;
        cascade<REG_A1 | REG_B1 | REG_B2 | REG_M | REG_P > dspN[size - 1];

     public:
        FIR(const long* coeff, long bias)
           : coeff_(coeff), bias_(bias) {
 #pragma HLS ARRAY_PARTITION variable=dspN complete dim=1
           };

        long fir(B_t input){

           auto out = dsp0.mul_add(coeff_[0], input, bias_);
           for(int j=1; j < size ; j++){
 #pragma HLS unroll
              out = dspN[j - 1].mul_add(coeff_[j], out.bcout, out.pcout);
           }
           return out.pcout;
        };
 };

 void test_cascaded_systolic_fir(long b[N], long c, long hw[N])
 {
    long a[4] = {1, 12, 3, 4}; // coefficients
 #pragma HLS ARRAY_PARTITION variable=a complete dim=1
 #pragma HLS ARRAY_PARTITION variable=hw complete dim=1
    FIR<4> my_fir(a, c);

    LOOP_FIR:
    for(int i = 0 ; i< N ; i++){
        hw[i] = my_fir.fir(b[i]);
    }
 }

Note the following details:

• Two different configurations of the cascaded DSPs are needed for the first stage of the
  cascade and the rest of the stages.

• Passing out.bcout and out.pcout as the b and c inputs of each mul_add call allows Vivado to
  use the bcin and pcin inputs of the next FIR stage.

    Guaranteed to use 4 DSPs (For example, 2 DSPCPLX instances)
  ○
    May or may not use the cascaded connection between them, because the Vitis HLS
  ○
    scheduler can insert registers between the DSPCPLX that may prevent the inference of the
    cascade collections.
    test_mul2 uses the cascade class to ensure both DSPCPLX inference and use of cascade
  ○
    connections (in this case, scheduling constraints are added to ensure that the proper
    number of registers is used between the DSPCPLX instances).

• Inference of DSPCPLX is guaranteed only for std::complex<ap_int<8>> and higher bitwidths.

 using namespace hls::dspcplx;

 // example of intrinsic method, inferencing one DSPCPLX
 void test_mul_add(
  ap_int<18> a_r, ap_int<18> a_i,
  ap_int<18> b_r, ap_int<18> b_i,
  ap_int<58> c_r, ap_int<58> c_i,
  ap_int<58>& r_r, ap_int<58>& r_i) {
    std::complex<ap_int<18>> a = {a_r, a_i};
    std::complex<ap_int<18>> b = {b_r, b_i};
    std::complex<ap_int<58>> c = {c_r, c_i};
    std::complex<ap_int<58>> r = mul_add<NO_PIPELINE | REG_M>(a, b, c);
    r_r = r.real();
    r_i = r.imag();
 }

// example of two intrinsic methods, inferencing two DSPCPLX
void test_mul1(A_t a0, A_t a1, B_t b0, B_t b1, C_t &r) {
   // computes z = a0 * b0 + a1 * b1
   C_t t = mul<FULL_PIPELINE>(a0, b0);
   r = mul_add<FULL_PIPELINE | REG_M>(a1, b1, t);
}

// same example as above, but using the cascade class to ensure cascaded
connection
void test_mul2(A_t a0, A_t a1, B_t b0, B_t b1, C_t &z) {
   #pragma HLS pipeline II=1
   // computes z = a0 * b0 + a1 * b1
   cascade<REG_A1|REG_B1|REG_M|REG_P > dsp0;
   cascade<REG_A1|REG_B1|REG_M|REG_P > dsp1;
   C_t zero = {0, 0};
   // mul is not available for cascade, so use mul_add(...,0);
   auto tmp = dsp0.mul_add(a0, b0, zero);
   auto out = dsp0.mul_add(a1, b1, tmp.pcout);
   z=out.pcout;
}

// example showing the acc class, inferencing one DSPCPLX (with accumulator)

const int N=10;

void test_mul_acc(A_t sr[N], B_t coeff[N], C_t &res) {
   C_t t = {0, 0};
   // computes t += sr[i] * coeff[i] for all i in {0 .. N-1}
   acc<BALANCED_PIPELINE | REG_M | REG_P> my_acc;
acc_loop:
   for (int i = 0; i < N; i++) {
       #pragma HLS pipeline II=1
       t = my_acc.mul_acc( sr[i], coeff[i], /* init condition */ i == 0);
   }
   res = t;
}

// example showing cascades to infer "size" DSPCPLX and using cascaded
connections
const int N=10;
const int TAPS=4;

template <int size>
class FIR{
    private:
       const A_t* coeff_;
       C_t bias_;
       cascade<BALANCED_PIPELINE|REG_M|REG_P > dsp0;
       cascade<  FULL_PIPELINE|REG_M|REG_P > dsp_full[size - 1];
    public:
       FIR(const A_t* coeff, C_t bias) : coeff_(coeff), bias_(bias) {
          #pragma HLS ARRAY_PARTITION variable=dsp_full complete dim=1
       };

       C_t fir(B_t input){
          auto out = dsp0.mul_add(coeff_[0], input, bias_);
          for(int j=1; j < size ; j++){
             #pragma HLS unroll
             out = dsp_full[j - 1].mul_add(coeff_[j], out.bcout,
out.pcout);
          }
          return out.pcout;

}; // end of fir function
}; // end of FIR class

void systolic_fir( A_t coeff[TAPS], B_t b[N], C_t bias, C_t hw[N]) {
   #pragma HLS ARRAY_PARTITION variable=coeff complete dim=1

   FIR<TAPS> my_fir(coeff, bias);

   LOOP_FIR:
   for(auto i = 0 ; i< N ; i++){
       #pragma HLS pipeline II=1
       hw[i] = my_fir.fir(b[i]);
   }
}

